function CommonActivityBossDropMessagePopUp:Awake()
	SetButtonAction(self.Root, function()
		UIModule.CloseDialog(self.controller)
	end)
	
	SetButtonAction(self.BtnClose, function()
		UIModule.CloseDialog(self.controller)
	end)
	
